    def bootstrap_pip(self, python):
        filename = f"pip-{BOOTSTRAP_PIP}-py3-none-any.whl"
        release = json.loads(fetch(f"https://pypi.org/pypi/pip/{BOOTSTRAP_PIP}/json"))
